import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import type { ReceiptData } from '../types';

const MARGIN = 50;
const PAGE_WIDTH = 612;
const PAGE_HEIGHT = 792;

function parseHex(hex: string) {
  const c = hex.replace('#', '');
  return {
    r: parseInt(c.substring(0, 2), 16) / 255,
    g: parseInt(c.substring(2, 4), 16) / 255,
    b: parseInt(c.substring(4, 6), 16) / 255,
  };
}

function formatCurrency(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(2)}`;
  }
}

/** Generate a single receipt PDF as Uint8Array */
export async function generateReceiptPdf(data: ReceiptData): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  const page = doc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontBold = await doc.embedFont(StandardFonts.HelveticaBold);

  const { organization, receiptType, transaction } = data;
  let y = PAGE_HEIGHT - MARGIN;
  const contentWidth = PAGE_WIDTH - MARGIN * 2;

  // ─── Logo ────────────────────────────────────────────────────────────────
  if (organization.logo) {
    try {
      const embedFn =
        organization.logo.mimeType === 'image/png' ? doc.embedPng : doc.embedJpg;
      const img = await embedFn.call(doc, organization.logo.data);
      const scale = Math.min(120 / img.width, 60 / img.height);
      const w = img.width * scale;
      const h = img.height * scale;
      page.drawImage(img, { x: MARGIN, y: y - h, width: w, height: h });
      y -= h + 12;
    } catch {
      // Skip logo on embed failure
    }
  }

  // ─── Organization Name ───────────────────────────────────────────────────
  page.drawText(organization.name, {
    x: MARGIN,
    y,
    size: 16,
    font: fontBold,
    color: rgb(0, 0, 0),
  });
  y -= 20;

  if (organization.address) {
    page.drawText(organization.address, { x: MARGIN, y, size: 9, font, color: rgb(0.4, 0.4, 0.4) });
    y -= 14;
  }

  // ─── Separator ───────────────────────────────────────────────────────────
  y -= 10;
  page.drawLine({
    start: { x: MARGIN, y },
    end: { x: PAGE_WIDTH - MARGIN, y },
    thickness: 1,
    color: rgb(0.8, 0.8, 0.8),
  });
  y -= 30;

  // ─── Title ───────────────────────────────────────────────────────────────
  const titleMap: Record<string, string> = {
    donation: 'Donation Receipt',
    invoice: 'Invoice',
    payment: 'Payment Receipt',
    custom: 'Receipt',
  };
  page.drawText(titleMap[receiptType] || 'Receipt', {
    x: MARGIN,
    y,
    size: 14,
    font: fontBold,
  });
  y -= 24;

  // ─── Receipt ID ──────────────────────────────────────────────────────────
  page.drawText(`Receipt #: ${transaction.referenceId}`, {
    x: MARGIN,
    y,
    size: 10,
    font,
    color: rgb(0.3, 0.3, 0.3),
  });
  y -= 30;

  // ─── Transaction Details ─────────────────────────────────────────────────
  const details: [string, string][] = [
    ['Recipient', transaction.recipientName],
    ['Amount', formatCurrency(transaction.amount, organization.currency)],
    ['Date', transaction.date],
    ['Payment Method', transaction.paymentMethod.replace('-', ' ')],
  ];
  if (transaction.notes) details.push(['Notes', transaction.notes]);

  for (const [label, value] of details) {
    page.drawText(`${label}:`, { x: MARGIN, y, size: 10, font: fontBold });
    page.drawText(value, { x: MARGIN + 120, y, size: 10, font });
    y -= 18;
  }

  // ─── Footer ──────────────────────────────────────────────────────────────
  const footerY = MARGIN + 40;
  page.drawLine({
    start: { x: MARGIN, y: footerY + 14 },
    end: { x: PAGE_WIDTH - MARGIN, y: footerY + 14 },
    thickness: 0.5,
    color: rgb(0.85, 0.85, 0.85),
  });

  page.drawText('This is a system-generated receipt.', {
    x: MARGIN,
    y: footerY,
    size: 8,
    font,
    color: rgb(0.5, 0.5, 0.5),
  });

  if (organization.taxDeductible) {
    page.drawText('This donation may be tax-deductible. No goods or services were provided in exchange.', {
      x: MARGIN,
      y: footerY - 12,
      size: 8,
      font,
      color: rgb(0.5, 0.5, 0.5),
    });
  }

  if (organization.footerText) {
    page.drawText(organization.footerText, {
      x: MARGIN,
      y: footerY - 24,
      size: 8,
      font,
      color: rgb(0.5, 0.5, 0.5),
    });
  }

  return doc.save();
}

