        </label>
        <input
          type="text"
          value={transaction.referenceId}
          onChange={(e) => update('referenceId', e.target.value)}
          className="w-full rounded-lg border border-secondary-300 dark:border-secondary-600 bg-white dark:bg-secondary-800 px-3 py-2 text-sm"
          placeholder="Auto-generated"
        />
      </div>

      {/* Notes */}
      <div>
        <label className="block text-sm font-medium text-secondary-700 dark:text-secondary-300 mb-1">
          Notes / Purpose
        </label>
        <textarea
          value={transaction.notes}
          onChange={(e) => update('notes', e.target.value)}
          rows={2}
          className="w-full rounded-lg border border-secondary-300 dark:border-secondary-600 bg-white dark:bg-secondary-800 px-3 py-2 text-sm resize-none"
          placeholder="General donation, Annual fund, etc."
        />
      </div>

      {/* Generate Button */}
      <Button
        variant="primary"
        fullWidth
        loading={generating}
        disabled={!transaction.recipientName || !transaction.amount}
        onClick={handleGenerate}
      >
        Generate Receipt PDF
      </Button>
    </div>
  );
}

