/**
 * Shared default values for the letterhead feature.
 * Used by both the visual editor (UI) and the export renderers (PDF/DOCX).
 */

export const DEFAULT_LETTER_BODY = `Date: September 22, 2025

Subject: [Your Subject Here]

Dear [Recipient Name],

We are writing to inform you about our upcoming initiative and to request your valued support. Our organization has been working diligently to serve our community and we believe that together we can achieve even greater impact.

Your contribution, whether large or small, will directly support our programs and help us continue our mission.

With gratitude,

[Your Name]
[Title]`;

/**
 * Get the effective letter body — returns the user's content or the default placeholder.
 * This is the single source of truth used by the editor, PDF export, and DOCX export.
 */
export function getEffectiveLetterBody(template: { letterBody?: string }): string {
  return template.letterBody ?? DEFAULT_LETTER_BODY;
}

/**
 * DOCX export for letterhead templates.
 * Generates a Word document (.docx) with the letterhead header and body text.
 * Optimized for compatibility with Apple Pages, Google Docs, and Microsoft Word.
 */
import { AlignmentType, BorderStyle, Document, ImageRun, Packer, Paragraph, TextRun } from 'docx';

import type { Alignment, LetterheadTemplate } from '../types';
import { getEffectiveLetterBody } from '../utils/defaults';

// US Letter in twips (1 inch = 1440 twips)
const LETTER_WIDTH = 12240; // 8.5 inches
const LETTER_HEIGHT = 15840; // 11 inches
const MARGIN_TWIPS = 1440; // 1 inch margins

/** Map template alignment to docx AlignmentType. */
function mapAlignment(alignment: Alignment): (typeof AlignmentType)[keyof typeof AlignmentType] {
  switch (alignment) {
    case 'center':
      return AlignmentType.CENTER;
    case 'right':
      return AlignmentType.RIGHT;
    default:
      return AlignmentType.LEFT;
  }
}

/** Strip '#' prefix from hex color for docx. */
function formatColor(hex: string): string {
  return hex.replace(/^#/, '');
}

/** Convert pt font size to half-points (docx uses half-points). */
function ptToHalfPoints(pt: number): number {
  return pt * 2;
}

/**
 * Map font family to a safe cross-platform font name.
 * Pages/Word/Docs all support these reliably.
 */
function safeFontFamily(fontFamily: string): string {
  switch (fontFamily) {
    case 'Helvetica':
      return 'Arial'; // Arial is the safe cross-platform equivalent
    case 'Times':
      return 'Times New Roman';
    case 'Courier':
      return 'Courier New';
    default:
      return 'Arial';
  }
}

/**
 * Export a letterhead template as a DOCX Blob.
 * Uses US Letter page size and cross-platform safe fonts.
 */
export async function exportLetterheadAsDocx(template: LetterheadTemplate): Promise<Blob> {
  const headerChildren: Paragraph[] = [];
  const defaultFont = safeFontFamily(template.companyName.fontFamily);

  // ─── Logo ────────────────────────────────────────────────────────────────
  if (template.logo && template.logo.data.byteLength > 0) {
    if (template.logo.mimeType === 'image/png' || template.logo.mimeType === 'image/jpeg') {
      const logoWidth = Math.min(template.logo.width, 200);
      const logoHeight = Math.round(logoWidth * 0.5);

      headerChildren.push(
        new Paragraph({
          alignment: mapAlignment(template.logo.alignment),
          spacing: { after: 200 },
          children: [
            new ImageRun({
              data: new Uint8Array(template.logo.data),
              transformation: { width: logoWidth, height: logoHeight },
              type: template.logo.mimeType === 'image/png' ? 'png' : 'jpg',
            }),
          ],
        }),
      );
    }
  }

  // ─── Company Name ────────────────────────────────────────────────────────
  if (template.companyName.content.trim()) {
    headerChildren.push(
      new Paragraph({
        alignment: mapAlignment(template.companyName.alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: template.companyName.content,
            font: safeFontFamily(template.companyName.fontFamily),
            size: ptToHalfPoints(template.companyName.fontSize),
            color: formatColor(template.companyName.color),
            bold: true,
          }),
        ],
      }),
    );
  }

  // ─── Tagline ─────────────────────────────────────────────────────────────
  if (template.tagline && template.tagline.content.trim()) {
    headerChildren.push(
      new Paragraph({
        alignment: mapAlignment(template.tagline.alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: template.tagline.content,
            font: safeFontFamily(template.tagline.fontFamily),
            size: ptToHalfPoints(template.tagline.fontSize),
            color: formatColor(template.tagline.color),
            italics: true,
          }),
        ],
      }),
    );
  }

  // ─── Contact Bar (single line with bullet separators) ────────────────────
  const contactParts: string[] = [];
  if (template.phone.content.trim()) contactParts.push(template.phone.content.trim());
  if (template.email.content.trim()) contactParts.push(template.email.content.trim());
  if (template.website.content.trim()) contactParts.push(template.website.content.trim());

  if (contactParts.length > 0) {
    headerChildren.push(
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: contactParts.join('  •  '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.phone.color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Address (single line) ───────────────────────────────────────────────
  const addressParts = template.addressLines
    .map((line) => line.content.trim())
    .filter(Boolean);

  if (addressParts.length > 0) {
    headerChildren.push(
      new Paragraph({
        alignment: mapAlignment(template.addressLines[0].alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: addressParts.join(', '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.addressLines[0].color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Separator ───────────────────────────────────────────────────────────
  if (template.showSeparator) {
    const sepColor = formatColor(template.separatorColor ?? '#cccccc');
    headerChildren.push(
      new Paragraph({
        spacing: { before: 200, after: 400 },
        border: {
          bottom: {
            style: BorderStyle.SINGLE,
            size: 8,
            color: sepColor,
          },
        },
      }),
    );
  } else {
    headerChildren.push(new Paragraph({ spacing: { after: 400 } }));
  }

  // ─── Body Content ─────────────────────────────────────────────────────────
  const bodyText = getEffectiveLetterBody(template);
  const bodyLines = bodyText.split('\n');
  const bodyParagraphs: Paragraph[] = bodyLines.map((line) =>
    new Paragraph({
      spacing: { after: line.trim() === '' ? 200 : 120, line: 276 },
      children: line.trim()
        ? [
            new TextRun({
              text: line,
              font: defaultFont,
              size: ptToHalfPoints(12),
              color: '000000',
            }),
          ]
        : [],
    }),
  );

  // ─── Document ────────────────────────────────────────────────────────────
  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            size: {
              width: LETTER_WIDTH,
              height: LETTER_HEIGHT,
            },
            margin: {
              top: MARGIN_TWIPS,
              right: MARGIN_TWIPS,
              bottom: MARGIN_TWIPS,
              left: MARGIN_TWIPS,
            },
          },
        },
        children: [...headerChildren, ...bodyParagraphs],
      },
    ],
  });

  return Packer.toBlob(doc);
}

