  deleteTemplate: (id) => {
    set((state) => ({
      templates: state.templates.filter((t) => t.id !== id),
      activeTemplateId: state.activeTemplateId === id ? null : state.activeTemplateId,
    }));
    get().saveToStorage();
  },

  duplicateTemplate: (id) => {
    const { templates } = get();
    if (templates.length >= MAX_TEMPLATES) {
      useToastStore
        .getState()
        .addToast(
          `Cannot duplicate template: maximum of ${MAX_TEMPLATES} templates reached. Delete unused templates to free space.`,
          'error',
        );
      return '';
    }

    const source = templates.find((t) => t.id === id);
    if (!source) return '';

    const now = Date.now();
    const newId = crypto.randomUUID();
    const duplicate: LetterheadTemplate = {
      ...source,
      id: newId,
      name: `${source.name} (Copy)`,
      createdAt: now,
      updatedAt: now,
    };

    set((state) => ({
      templates: [...state.templates, duplicate],
    }));
    get().saveToStorage();
    return newId;
  },

  renameTemplate: (id, name) => {
    const now = Date.now();
    set((state) => ({
      templates: state.templates.map((t) => (t.id === id ? { ...t, name, updatedAt: now } : t)),
    }));
    get().saveToStorage();
  },

  selectTemplate: (id) => {
    set({ activeTemplateId: id, lastUsedTemplateId: id });
    try {
      localStorage.setItem(LAST_USED_KEY, id);
    } catch {
      // Ignore storage errors for last-used tracking
    }
  },

  setEditorState: (state) => {
    set({ editorState: state });
  },

  loadFromStorage: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          // Restore ArrayBuffer from base64 for logo data
          const restored = parsed.map((t: Record<string, unknown>) => {
            if (t.logo && typeof (t.logo as Record<string, unknown>).dataBase64 === 'string') {
              const logo = t.logo as Record<string, unknown>;
              const binary = atob(logo.dataBase64 as string);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) {
                bytes[i] = binary.charCodeAt(i);
              }
              return { ...t, logo: { ...logo, data: bytes.buffer, dataBase64: undefined } };
            }
            return t;
          });
          set({ templates: restored as unknown as LetterheadTemplate[] });
        }
      }
    } catch {
      // Graceful fallback: keep empty templates array on parse error
    }

    try {
      const lastUsed = localStorage.getItem(LAST_USED_KEY);
      if (lastUsed) {
        set({ lastUsedTemplateId: lastUsed });
      }
    } catch {
      // Ignore storage read errors for last-used
    }
  },

  saveToStorage: () => {
    const { templates } = get();
    try {
      // Convert ArrayBuffer logo data to base64 for JSON serialization
      const serializable = templates.map((t) => {
        if (t.logo && t.logo.data instanceof ArrayBuffer && t.logo.data.byteLength > 0) {
          const bytes = new Uint8Array(t.logo.data);
          let binary = '';
          for (let i = 0; i < bytes.length; i++) {
            binary += String.fromCharCode(bytes[i]);
          }
          const dataBase64 = btoa(binary);
          return { ...t, logo: { ...t.logo, data: undefined, dataBase64 } };
        }
        return t;
      });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(serializable));
    } catch (error: unknown) {
      if (error instanceof DOMException && error.name === 'QuotaExceededError') {
        useToastStore
          .getState()
          .addToast('Storage is full. Delete unused templates to free space.', 'error');
      }
    }
  },
}));

