/**
 * DOCX export for letterhead templates.
 * Generates a Word document (.docx) with the letterhead header and body text.
 * Properly handles all layout types including the 3-column logo-center layout.
 */
import {
  AlignmentType,
  BorderStyle,
  Document,
  ImageRun,
  Packer,
  Paragraph,
  Table,
  TableCell,
  TableRow,
  TextRun,
  WidthType,
  VerticalAlign,
} from 'docx';

import type { Alignment, LetterheadTemplate } from '../types';
import { getEffectiveLetterBody } from '../utils/defaults';

const LETTER_WIDTH = 12240;
const LETTER_HEIGHT = 15840;
const MARGIN_TWIPS = 1440;

function mapAlignment(alignment: Alignment): (typeof AlignmentType)[keyof typeof AlignmentType] {
  switch (alignment) {
    case 'center':
      return AlignmentType.CENTER;
    case 'right':
      return AlignmentType.RIGHT;
    default:
      return AlignmentType.LEFT;
  }
}

function formatColor(hex: string): string {
  return hex.replace(/^#/, '');
}

function ptToHalfPoints(pt: number): number {
  return pt * 2;
}

function safeFontFamily(fontFamily: string): string {
  switch (fontFamily) {
    case 'Helvetica':
      return 'Arial';
    case 'Times':
      return 'Times New Roman';
    case 'Courier':
      return 'Courier New';
    default:
      return 'Arial';
  }
}

const noBorders = {
  top: { style: BorderStyle.NONE, size: 0 },
  bottom: { style: BorderStyle.NONE, size: 0 },
  left: { style: BorderStyle.NONE, size: 0 },
  right: { style: BorderStyle.NONE, size: 0 },
} as const;

/** Build the header section based on the template layout */
function buildHeader(template: LetterheadTemplate): (Paragraph | Table)[] {
  const layout = template.layout ?? 'centered';
  const defaultFont = safeFontFamily(template.companyName.fontFamily);
  const headerColor = formatColor(template.companyName.color);
  const headerSize = ptToHalfPoints(template.companyName.fontSize);
  const children: (Paragraph | Table)[] = [];

  if (layout === 'logo-center') {
    // ─── 3-column layout: [Left Text] [Logo] [Right Text] ───────────────
    const leftLines = (template.headerLeftText ?? '').split('\n');
    const rightLines = (template.headerRightText ?? '').split('\n');

    const leftParagraphs = leftLines.map(
      (line) =>
        new Paragraph({
          alignment: AlignmentType.RIGHT,
          spacing: { after: 40 },
          children: line.trim()
            ? [new TextRun({ text: line, font: defaultFont, size: ptToHalfPoints(10), color: headerColor, bold: true })]
            : [],
        }),
    );

    const rightParagraphs = rightLines.map(
      (line) =>
        new Paragraph({
          alignment: AlignmentType.LEFT,
          spacing: { after: 40 },
          children: line.trim()
            ? [new TextRun({ text: line, font: defaultFont, size: ptToHalfPoints(10), color: headerColor, bold: true })]
            : [],
        }),
    );

    // Center cell — logo or "Logo" placeholder text
    const centerChildren: Paragraph[] = [];
    if (template.logo && template.logo.data.byteLength > 0 &&
        (template.logo.mimeType === 'image/png' || template.logo.mimeType === 'image/jpeg')) {
      const logoWidth = Math.min(template.logo.width, 120);
      const logoHeight = Math.round(logoWidth * 0.6);
      centerChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [
            new ImageRun({
              data: new Uint8Array(template.logo.data),
              transformation: { width: logoWidth, height: logoHeight },
              type: template.logo.mimeType === 'image/png' ? 'png' : 'jpg',
            }),
          ],
        }),
      );
    } else {
      centerChildren.push(
        new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: '' })] }),
      );
    }

    const contentWidth = LETTER_WIDTH - MARGIN_TWIPS * 2; // usable width in twips
    children.push(
      new Table({
        rows: [
          new TableRow({
            children: [
              new TableCell({
                width: { size: Math.round(contentWidth * 0.35), type: WidthType.DXA },
                borders: noBorders,
                verticalAlign: VerticalAlign.CENTER,
                children: leftParagraphs.length > 0 ? leftParagraphs : [new Paragraph('')],
              }),
              new TableCell({
                width: { size: Math.round(contentWidth * 0.30), type: WidthType.DXA },
                borders: noBorders,
                verticalAlign: VerticalAlign.CENTER,
                children: centerChildren,
              }),
              new TableCell({
                width: { size: Math.round(contentWidth * 0.35), type: WidthType.DXA },
                borders: noBorders,
                verticalAlign: VerticalAlign.CENTER,
                children: rightParagraphs.length > 0 ? rightParagraphs : [new Paragraph('')],
              }),
            ],
          }),
        ],
        width: { size: contentWidth, type: WidthType.DXA },
      }),
    );
  } else {
    // ─── All other layouts: Logo then Company Name ──────────────────────
    if (template.logo && template.logo.data.byteLength > 0 &&
        (template.logo.mimeType === 'image/png' || template.logo.mimeType === 'image/jpeg')) {
      const logoWidth = Math.min(template.logo.width, 200);
      const logoHeight = Math.round(logoWidth * 0.5);
      children.push(
        new Paragraph({
          alignment: mapAlignment(template.logo.alignment),
          spacing: { after: 200 },
          children: [
            new ImageRun({
              data: new Uint8Array(template.logo.data),
              transformation: { width: logoWidth, height: logoHeight },
              type: template.logo.mimeType === 'image/png' ? 'png' : 'jpg',
            }),
          ],
        }),
      );
    }

    if (template.companyName.content.trim()) {
      children.push(
        new Paragraph({
          alignment: mapAlignment(template.companyName.alignment),
          spacing: { after: 120 },
          children: [
            new TextRun({
              text: template.companyName.content,
              font: safeFontFamily(template.companyName.fontFamily),
              size: headerSize,
              color: headerColor,
              bold: true,
            }),
          ],
        }),
      );
    }
  }

  // ─── Tagline ─────────────────────────────────────────────────────────────
  if (template.tagline && template.tagline.content.trim()) {
    children.push(
      new Paragraph({
        alignment: mapAlignment(template.tagline.alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: template.tagline.content,
            font: safeFontFamily(template.tagline.fontFamily),
            size: ptToHalfPoints(template.tagline.fontSize),
            color: formatColor(template.tagline.color),
            italics: true,
          }),
        ],
      }),
    );
  }

  // ─── Contact Bar ─────────────────────────────────────────────────────────
  const contactParts: string[] = [];
  if (template.phone.content.trim()) contactParts.push(template.phone.content.trim());
  if (template.email.content.trim()) contactParts.push(template.email.content.trim());
  if (template.website.content.trim()) contactParts.push(template.website.content.trim());

  if (contactParts.length > 0) {
    children.push(
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: contactParts.join('  •  '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.phone.color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Address ─────────────────────────────────────────────────────────────
  const addressParts = template.addressLines.map((l) => l.content.trim()).filter(Boolean);
  if (addressParts.length > 0) {
    children.push(
      new Paragraph({
        alignment: mapAlignment(template.addressLines[0].alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: addressParts.join(', '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.addressLines[0].color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Separator ───────────────────────────────────────────────────────────
  if (template.showSeparator) {
    children.push(
      new Paragraph({
        spacing: { before: 200, after: 400 },
        border: {
          bottom: { style: BorderStyle.SINGLE, size: 8, color: formatColor(template.separatorColor ?? '#cccccc') },
        },
      }),
    );
  } else {
    children.push(new Paragraph({ spacing: { after: 400 } }));
  }

  return children;
}

/**
 * Export a letterhead template as a DOCX Blob.
 */
export async function exportLetterheadAsDocx(template: LetterheadTemplate): Promise<Blob> {
  const defaultFont = safeFontFamily(template.companyName.fontFamily);
  const headerElements = buildHeader(template);

  // ─── Body ──────────────────────────────────────────────────────────────────
  const bodyText = getEffectiveLetterBody(template);
  const bodyParagraphs: Paragraph[] = bodyText.split('\n').map(
    (line) =>
      new Paragraph({
        spacing: { after: line.trim() === '' ? 200 : 120, line: 276 },
        children: line.trim()
          ? [new TextRun({ text: line, font: defaultFont, size: ptToHalfPoints(12), color: '000000' })]
          : [],
      }),
  );

  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            size: { width: LETTER_WIDTH, height: LETTER_HEIGHT },
            margin: { top: MARGIN_TWIPS, right: MARGIN_TWIPS, bottom: MARGIN_TWIPS, left: MARGIN_TWIPS },
          },
        },
        children: [...headerElements, ...bodyParagraphs],
      },
    ],
  });

  return Packer.toBlob(doc);
}

