    const leftText = (template.headerLeftText ?? '').replace(/\n/g, '  ');
    const rightText = (template.headerRightText ?? '').replace(/\n/g, '  ');

    if (leftText.trim() || rightText.trim()) {
      headerChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 120 },
          children: [
            new TextRun({
              text: [leftText.trim(), rightText.trim()].filter(Boolean).join('     '),
              font: defaultFont,
              size: ptToHalfPoints(template.companyName.fontSize),
              color: formatColor(template.companyName.color),
              bold: true,
            }),
          ],
        }),
      );
    }
  } else {
    // For all other layouts: use companyName
    if (template.companyName.content.trim()) {
      headerChildren.push(
        new Paragraph({
          alignment: mapAlignment(template.companyName.alignment),
          spacing: { after: 120 },
          children: [
            new TextRun({
              text: template.companyName.content,
              font: safeFontFamily(template.companyName.fontFamily),
              size: ptToHalfPoints(template.companyName.fontSize),
              color: formatColor(template.companyName.color),
              bold: true,
            }),
          ],
        }),
      );
    }
  }

  // ─── Tagline ─────────────────────────────────────────────────────────────
  if (template.tagline && template.tagline.content.trim()) {
    headerChildren.push(
      new Paragraph({
        alignment: mapAlignment(template.tagline.alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: template.tagline.content,
            font: safeFontFamily(template.tagline.fontFamily),
            size: ptToHalfPoints(template.tagline.fontSize),
            color: formatColor(template.tagline.color),
            italics: true,
          }),
        ],
      }),
    );
  }

  // ─── Contact Bar ─────────────────────────────────────────────────────────
  const contactParts: string[] = [];
  if (template.phone.content.trim()) contactParts.push(template.phone.content.trim());
  if (template.email.content.trim()) contactParts.push(template.email.content.trim());
  if (template.website.content.trim()) contactParts.push(template.website.content.trim());

  if (contactParts.length > 0) {
    headerChildren.push(
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: contactParts.join('  •  '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.phone.color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Address ─────────────────────────────────────────────────────────────
  const addressParts = template.addressLines.map((line) => line.content.trim()).filter(Boolean);
  if (addressParts.length > 0) {
    headerChildren.push(
      new Paragraph({
        alignment: mapAlignment(template.addressLines[0].alignment),
        spacing: { after: 120 },
        children: [
          new TextRun({
            text: addressParts.join(', '),
            font: defaultFont,
            size: ptToHalfPoints(9),
            color: formatColor(template.addressLines[0].color || '#6b7280'),
          }),
        ],
      }),
    );
  }

  // ─── Separator ───────────────────────────────────────────────────────────
  if (template.showSeparator) {
    headerChildren.push(
      new Paragraph({
        spacing: { before: 200, after: 400 },
        border: {
          bottom: { style: BorderStyle.SINGLE, size: 8, color: formatColor(template.separatorColor ?? '#cccccc') },
        },
      }),
    );
  } else {
    headerChildren.push(new Paragraph({ spacing: { after: 400 } }));
  }

  // ─── Body Content ─────────────────────────────────────────────────────────
  const bodyText = getEffectiveLetterBody(template);
  const bodyParagraphs: Paragraph[] = bodyText.split('\n').map(
    (line) =>
      new Paragraph({
        spacing: { after: line.trim() === '' ? 200 : 120, line: 276 },
        children: line.trim()
          ? [new TextRun({ text: line, font: defaultFont, size: ptToHalfPoints(12), color: '000000' })]
          : [],
      }),
  );

  // ─── Document ────────────────────────────────────────────────────────────
  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            size: { width: LETTER_WIDTH, height: LETTER_HEIGHT },
            margin: { top: MARGIN_TWIPS, right: MARGIN_TWIPS, bottom: MARGIN_TWIPS, left: MARGIN_TWIPS },
          },
        },
        children: [...headerChildren, ...bodyParagraphs],
      },
    ],
  });

  return Packer.toBlob(doc);
}

