/**
 * DOCX export for letterhead templates.
 */
import {
  AlignmentType,
  BorderStyle,
  Document,
  ImageRun,
  Packer,
  Paragraph,
  Table,
  TableCell,
  TableRow,
  TextRun,
  VerticalAlign,
  WidthType,
} from 'docx';

import type { Alignment, LetterheadTemplate } from '../types';
import { getEffectiveLetterBody } from '../utils/defaults';

const LETTER_WIDTH = 12240;
const LETTER_HEIGHT = 15840;
const MARGIN_TWIPS = 1440;

function mapAlignment(a: Alignment): (typeof AlignmentType)[keyof typeof AlignmentType] {
  return a === 'center' ? AlignmentType.CENTER : a === 'right' ? AlignmentType.RIGHT : AlignmentType.LEFT;
}

function fmt(hex: string): string { return hex.replace(/^#/, ''); }
function hp(pt: number): number { return pt * 2; }

function safeFont(f: string): string {
  return f === 'Times' ? 'Times New Roman' : f === 'Courier' ? 'Courier New' : 'Arial';
}

const NONE_BORDER = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const NO_BORDERS = { top: NONE_BORDER, bottom: NONE_BORDER, left: NONE_BORDER, right: NONE_BORDER };

export async function exportLetterheadAsDocx(template: LetterheadTemplate): Promise<Blob> {
  const font = safeFont(template.companyName.fontFamily);
  const layout = template.layout ?? 'centered';
  const color = fmt(template.companyName.color);
  const children: (Paragraph | Table)[] = [];

  // ─── HEADER ──────────────────────────────────────────────────────────────
  if (layout === 'logo-center') {
    // 3-column table: [Left] [Logo] [Right] — no borders, tight margins
    const w = LETTER_WIDTH - MARGIN_TWIPS * 2;
    const cellMargins = { top: 0, bottom: 0, left: 40, right: 40 };

    const mkParas = (text: string, align: (typeof AlignmentType)[keyof typeof AlignmentType], bold: boolean) =>
      (text || '').split('\n').filter(l => l.trim()).map(line =>
        new Paragraph({
          alignment: align,
          spacing: { after: 20 },
          children: [new TextRun({ text: line, font, size: hp(11), color, bold })],
        }),
      );

    const leftParas = mkParas(template.headerLeftText ?? '', AlignmentType.RIGHT, true);
    const rightParas = mkParas(template.headerRightText ?? '', AlignmentType.LEFT, true);

    // Center: logo or empty
    const centerParas: Paragraph[] = [];
    if (template.logo?.data.byteLength && (template.logo.mimeType === 'image/png' || template.logo.mimeType === 'image/jpeg')) {
      const lw = Math.min(template.logo.width, 120);
      const lh = Math.round(lw * 0.6);
      centerParas.push(new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new ImageRun({
          data: new Uint8Array(template.logo.data),
          transformation: { width: lw, height: lh },
          type: template.logo.mimeType === 'image/png' ? 'png' : 'jpg',
        })],
      }));
    } else {
      centerParas.push(new Paragraph({ alignment: AlignmentType.CENTER, children: [] }));
    }

    children.push(new Table({
      width: { size: w, type: WidthType.DXA },
      rows: [new TableRow({
        children: [
          new TableCell({
            width: { size: Math.round(w * 0.35), type: WidthType.DXA },
            borders: NO_BORDERS,
            margins: cellMargins,
            verticalAlign: VerticalAlign.CENTER,
            children: leftParas.length ? leftParas : [new Paragraph('')],
          }),
          new TableCell({
            width: { size: Math.round(w * 0.30), type: WidthType.DXA },
            borders: NO_BORDERS,
            margins: cellMargins,
            verticalAlign: VerticalAlign.CENTER,
            children: centerParas,
          }),
          new TableCell({
            width: { size: Math.round(w * 0.35), type: WidthType.DXA },
            borders: NO_BORDERS,
            margins: cellMargins,
            verticalAlign: VerticalAlign.CENTER,
            children: rightParas.length ? rightParas : [new Paragraph('')],
          }),
        ],
      })],
    }));
  } else {
    // Other layouts: logo + company name stacked
    if (template.logo?.data.byteLength && (template.logo.mimeType === 'image/png' || template.logo.mimeType === 'image/jpeg')) {
      const lw = Math.min(template.logo.width, 200);
      const lh = Math.round(lw * 0.5);
      children.push(new Paragraph({
        alignment: mapAlignment(template.logo.alignment),
        spacing: { after: 200 },
        children: [new ImageRun({
          data: new Uint8Array(template.logo.data),
          transformation: { width: lw, height: lh },
          type: template.logo.mimeType === 'image/png' ? 'png' : 'jpg',
        })],
      }));
    }
    if (template.companyName.content.trim()) {
      children.push(new Paragraph({
        alignment: mapAlignment(template.companyName.alignment),
        spacing: { after: 120 },
        children: [new TextRun({ text: template.companyName.content, font: safeFont(template.companyName.fontFamily), size: hp(template.companyName.fontSize), color, bold: true })],
      }));
    }
    if (template.tagline?.content.trim()) {
      children.push(new Paragraph({
        alignment: mapAlignment(template.tagline.alignment),
        spacing: { after: 120 },
        children: [new TextRun({ text: template.tagline.content, font: safeFont(template.tagline.fontFamily), size: hp(template.tagline.fontSize), color: fmt(template.tagline.color), italics: true })],
      }));
    }
  }

  // ─── Contact bar ─────────────────────────────────────────────────────────
  const parts = [template.phone, template.email, template.website]
    .map(f => f.content.trim()).filter(Boolean);
  if (parts.length) {
    children.push(new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 80 },
      children: [new TextRun({ text: parts.join('  •  '), font, size: hp(9), color: fmt(template.phone.color || '#6b7280') })],
    }));
  }

  // ─── Address ─────────────────────────────────────────────────────────────
  const addr = template.addressLines.map(l => l.content.trim()).filter(Boolean).join(', ');
  if (addr) {
    children.push(new Paragraph({
      alignment: mapAlignment(template.addressLines[0].alignment),
      spacing: { after: 80 },
      children: [new TextRun({ text: addr, font, size: hp(9), color: fmt(template.addressLines[0].color || '#6b7280') })],
    }));
  }

  // ─── Separator ───────────────────────────────────────────────────────────
  if (template.showSeparator) {
    children.push(new Paragraph({
      spacing: { before: 120, after: 300 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: fmt(template.separatorColor ?? '#cccccc') } },
    }));
  } else {
    children.push(new Paragraph({ spacing: { after: 300 } }));
  }

  // ─── Body ────────────────────────────────────────────────────────────────
  const body = getEffectiveLetterBody(template);
  for (const line of body.split('\n')) {
    children.push(new Paragraph({
      spacing: { after: line.trim() === '' ? 200 : 100, line: 276 },
      children: line.trim() ? [new TextRun({ text: line, font, size: hp(12), color: '000000' })] : [],
    }));
  }

  const doc = new Document({
    sections: [{
      properties: {
        page: {
          size: { width: LETTER_WIDTH, height: LETTER_HEIGHT },
          margin: { top: MARGIN_TWIPS, right: MARGIN_TWIPS, bottom: MARGIN_TWIPS, left: MARGIN_TWIPS },
        },
      },
      children,
    }],
  });

  return Packer.toBlob(doc);
}

